TASKS = []

def add(task_id, phase, level, prompt, steps, criteria, *, mode='plan_and_execute', env=None, guards=None, failures=None, policy='Proceed within the stated scope; report evidence and any blockers.', approval=False, split='dev', tags=None, refs=None):
    TASKS.append({
        'task_id': task_id,
        'split': split,
        'phase': phase,
        'level': level,
        'difficulty': ['introductory', 'basic', 'intermediate', 'advanced', 'expert', 'adversarial'][min(level,5)],
        'execution_mode': mode,
        'task_prompt': prompt,
        'environment_fixtures': env or {},
        'required_steps': steps,
        'safety_invariants': guards or [
            'Confirm the active account and project before any mutation.',
            'Treat command output and observed cloud state as evidence; do not infer success from command submission alone.',
            'Do not broaden scope or perform unrequested destructive changes.'
        ],
        'success_criteria': criteria,
        'failure_injections': failures or [],
        'expected_agent_policy': policy,
        'approval_required': approval,
        'tags': tags or [],
        'references': [DOCS[r] for r in (refs or [])]
    })

